window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-64b9aa2365081762"]={"versions": [{"id": "FIG-64b9aa2365081762", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm mit Interaktionsreferenzen (<code>ref</code>-Frames / Interaction Use).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Spezifikation des ECU State Managers (<code>AUTOSAR_SWS_ECUStateManager</code>).\n</li><li><strong>Funktionaler Zweck:</strong> Darstellung der Phasenübergänge und des Kontrollflusses während der Initialisierungssequenz (<strong>STARTUP Phase</strong>) des Steuergeräts vom Hardware-Reset über den C-Laufzeitaufbau (Pre-OS) bis zur Übergabe an das Betriebssystem (OS) und die anschließende Wiederaufnahme durch den EcuM (Post-OS).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>Reset</code>: Externer Hardware-Reset-Auslöser (Power-On-Reset, Watchdog, Software-Reset).\n</li><li><code>Boot Menu</code>: Bootloader- / Hardware-Startup-Code bzw. Reset-Handler-Einsprungpunkt.\n</li><li><code>C Init Code</code>: Hardwarenaher C-Laufzeit-Startup (Zeroing <code>.bss</code>, Initialisieren von <code>.data</code>, Stack-Pointer-Konfiguration).\n</li><li><code>«module» Os</code>: AUTOSAR Operating System (Klasse: Systemdienst / Basissoftware-Modul).\n</li><li><code>BSW Task (OS task or cyclic call)</code>: Spezifische OS-Task (Autostart-Task) zur Ausführung zyklischer oder sequentieller Basissoftware-Abläufe.\n</li><li><code>«module» EcuM</code>: ECU State Manager (Klasse: Systemdienst-Modul zur zentralen Verwaltung der ECU-Zustände).\n</li></ul>\n</li><li><strong>Interaktionsreferenzen (<code>ref</code>):</strong>\n<ul class=\"fig-list\"><li><code>StartPreOS Sequence</code>: Kapselt EcuM-Initialisierungsschritte vor Start des Kernels (u. a. <code>EcuM_InitDriverInitBlock(0)</code>, Det-, Dem- und Basistreiberinitialisierung).\n</li><li><code>StartPostOS Sequence</code>: Kapselt Initialisierungsschritte nach OS-Start (u. a. Scheduler-Start via SchM, <code>BswM_Init</code>, Treiberinitialisierung Block 2/3).\n</li></ul>\n</li><li><strong>Schnittstellen / Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>Reset Vector()</code>: Hardwarespezifischer Eintrittsvektor.\n</li><li><code>Jump()</code>: Direkter Verzweigungsbefehl in die C-Laufzeit-Initialisierung.\n</li><li><code>Set up stack()</code>: Interner Aufruf zur Konfiguration der CPU-Register und Stack-Pointer.\n</li><li><code>EcuM_Init()</code>: Synchrone Einstiegs-API des EcuM vor OS-Start.\n</li><li><code>StartOS()</code>: Kernelschnittstelle zum Hochfahren des OS (übernimmt die Ausführungskontrolle).\n</li><li><code>StartupHook()</code>: Konfigurierbarer OS-Callback für anwendungsspezifischen Pre-Task-Code.\n</li><li><code>ActivateTask()</code>: OS-Systemdienst zur Aktivierung der initialen BSW-Task (bzw. impliziter Task-Start via OS-Autostart).\n</li><li><code>EcuM_StartupTwo()</code>: Synchrone EcuM-API zur Fortsetzung der Startup-Sequenz im Task-Kontext.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>Reset</code> springt den <code>Reset Vector()</code> der Bootloader-/Boot-Menu-Logik an.\n</li><li><strong>Low-Level Startup:</strong> <code>Boot Menu</code> verzweigt via <code>Jump()</code> in den <code>C Init Code</code>.\n</li><li><strong>C-Laufzeit:</strong> <code>C Init Code</code> führt <code>Set up stack()</code> aus und initialisiert Speichersektionen.\n</li><li><strong>Pre-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Synchroner Aufruf von <code>EcuM_Init()</code>.\n</li><li>Ausführung der <code>StartPreOS Sequence</code>: Minimale Hardwaretreiber-Initialisierung (u. a. MCU, Base Clocks, Pre-OS I/O) und Konfiguration der Basistreiber.\n</li></ul>\n</li><li><strong>Kontrollabgabe an das OS:</strong>\n<ul class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>StartOS()</code> auf; der Kontrollfluss verlässt die <code>EcuM_Init()</code>-Sequenz dauerhaft (kein direkter Return von <code>StartOS</code>).\n</li></ul>\n</li><li><strong>OS-Initialisierung:</strong>\n<ul class=\"fig-list\"><li>Der OS-Kernel übernimmt die CPU-Kontrolle und ruft optional den synchronen <code>StartupHook()</code> auf.\n</li><li>Das OS aktiviert die BSW-Starttask (explizit via <code>ActivateTask()</code> oder konfiguriert als <code>AUTOSTART = TRUE</code>).\n</li></ul>\n</li><li><strong>Post-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Als allererste Aktion innerhalb der BSW-Task wird <code>EcuM_StartupTwo()</code> synchron aufgerufen.\n</li><li><code>EcuM</code> führt die <code>StartPostOS Sequence</code> aus (Initialisierung der verbleibenden BSW-Stacks, SchM, Start der BSW-Scheduler-Loops).\n</li><li>Nach Rückkehr von <code>EcuM_StartupTwo()</code> setzt die Task ihre reguläre Ausführung fort (z. B. Übergang in zyklische Ausführung oder Beenden via <code>TerminateTask()</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag &amp; Kontrollflussverlust:</strong> <code>StartOS()</code> kehrt gemäß OSEK/AUTOSAR OS-Spezifikation <strong>nie</strong> zum Aufrufer zurück. <code>EcuM_Init()</code> wird somit niemals regulär beendet.\n</li><li><strong>Integrationspflicht (Autostart-Task):</strong> Der System-Integrator muss zwingend eine OS-Task konfigurieren (<code>AUTOSTART = TRUE</code> im OIL/ARXML), deren <strong>allererste Anweisung</strong> der Aufruf von <code>EcuM_StartupTwo()</code> ist. Jede Verzögerung oder vorherige Task-Aktivität verletzt den Startup-Vertrag.\n</li><li><strong>Kontextbedingungen:</strong>\n<ul class=\"fig-list\"><li>In <code>StartPreOS Sequence</code> (<code>EcuM_Init</code>): Kein Tasking, keine OS-Ressourcen/Events, Interrupts typischerweise global gesperrt (<code>SuspendAllInterrupts</code> oder HW-Level). Nur zustandslose Basistreiber zulässig.\n</li><li>In <code>StartPostOS Sequence</code> (<code>EcuM_StartupTwo</code>): Voller Task-Kontext verfügbar; Inter-Modul-Kommunikation und OS-Dienste (Events, SchM) sind betriebsbereit.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Fehler in der <code>StartPreOS Sequence</code> vor Initialisierung von Dem/Det führen in hardwarenahe Trap-/Reset-Handler oder Endlosschleifen (<code>EcuM_ErrorHook</code>). Erst in <code>EcuM_StartupTwo()</code> steht die vollständige Diagnose- und Fehlerberichterstattung zur Verfügung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e330869822abb792", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm mit Interaktionsreferenzen (<code>ref</code>-Frames / Interaction Use).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Spezifikation des ECU State Managers (<code>AUTOSAR_SWS_ECUStateManager</code>).\n</li><li><strong>Funktionaler Zweck:</strong> Darstellung der Phasenübergänge und des Kontrollflusses während der Initialisierungssequenz (<strong>STARTUP Phase</strong>) des Steuergeräts vom Hardware-Reset über den C-Laufzeitaufbau (Pre-OS) bis zur Übergabe an das Betriebssystem (OS) und die anschließende Wiederaufnahme durch den EcuM (Post-OS).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>Reset</code>: Externer Hardware-Reset-Auslöser (Power-On-Reset, Watchdog, Software-Reset).\n</li><li><code>Boot Menu</code>: Bootloader- / Hardware-Startup-Code bzw. Reset-Handler-Einsprungpunkt.\n</li><li><code>C Init Code</code>: Hardwarenaher C-Laufzeit-Startup (Zeroing <code>.bss</code>, Initialisieren von <code>.data</code>, Stack-Pointer-Konfiguration).\n</li><li><code>«module» Os</code>: AUTOSAR Operating System (Klasse: Systemdienst / Basissoftware-Modul).\n</li><li><code>BSW Task (OS task or cyclic call)</code>: Spezifische OS-Task (Autostart-Task) zur Ausführung zyklischer oder sequentieller Basissoftware-Abläufe.\n</li><li><code>«module» EcuM</code>: ECU State Manager (Klasse: Systemdienst-Modul zur zentralen Verwaltung der ECU-Zustände).\n</li></ul>\n</li><li><strong>Interaktionsreferenzen (<code>ref</code>):</strong>\n<ul class=\"fig-list\"><li><code>StartPreOS Sequence</code>: Kapselt EcuM-Initialisierungsschritte vor Start des Kernels (u. a. <code>EcuM_InitDriverInitBlock(0)</code>, Det-, Dem- und Basistreiberinitialisierung).\n</li><li><code>StartPostOS Sequence</code>: Kapselt Initialisierungsschritte nach OS-Start (u. a. Scheduler-Start via SchM, <code>BswM_Init</code>, Treiberinitialisierung Block 2/3).\n</li></ul>\n</li><li><strong>Schnittstellen / Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>Reset Vector()</code>: Hardwarespezifischer Eintrittsvektor.\n</li><li><code>Jump()</code>: Direkter Verzweigungsbefehl in die C-Laufzeit-Initialisierung.\n</li><li><code>Set up stack()</code>: Interner Aufruf zur Konfiguration der CPU-Register und Stack-Pointer.\n</li><li><code>EcuM_Init()</code>: Synchrone Einstiegs-API des EcuM vor OS-Start.\n</li><li><code>StartOS()</code>: Kernelschnittstelle zum Hochfahren des OS (übernimmt die Ausführungskontrolle).\n</li><li><code>StartupHook()</code>: Konfigurierbarer OS-Callback für anwendungsspezifischen Pre-Task-Code.\n</li><li><code>ActivateTask()</code>: OS-Systemdienst zur Aktivierung der initialen BSW-Task (bzw. impliziter Task-Start via OS-Autostart).\n</li><li><code>EcuM_StartupTwo()</code>: Synchrone EcuM-API zur Fortsetzung der Startup-Sequenz im Task-Kontext.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>Reset</code> springt den <code>Reset Vector()</code> der Bootloader-/Boot-Menu-Logik an.\n</li><li><strong>Low-Level Startup:</strong> <code>Boot Menu</code> verzweigt via <code>Jump()</code> in den <code>C Init Code</code>.\n</li><li><strong>C-Laufzeit:</strong> <code>C Init Code</code> führt <code>Set up stack()</code> aus und initialisiert Speichersektionen.\n</li><li><strong>Pre-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Synchroner Aufruf von <code>EcuM_Init()</code>.\n</li><li>Ausführung der <code>StartPreOS Sequence</code>: Minimale Hardwaretreiber-Initialisierung (u. a. MCU, Base Clocks, Pre-OS I/O) und Konfiguration der Basistreiber.\n</li></ul>\n</li><li><strong>Kontrollabgabe an das OS:</strong>\n<ul class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>StartOS()</code> auf; der Kontrollfluss verlässt die <code>EcuM_Init()</code>-Sequenz dauerhaft (kein direkter Return von <code>StartOS</code>).\n</li></ul>\n</li><li><strong>OS-Initialisierung:</strong>\n<ul class=\"fig-list\"><li>Der OS-Kernel übernimmt die CPU-Kontrolle und ruft optional den synchronen <code>StartupHook()</code> auf.\n</li><li>Das OS aktiviert die BSW-Starttask (explizit via <code>ActivateTask()</code> oder konfiguriert als <code>AUTOSTART = TRUE</code>).\n</li></ul>\n</li><li><strong>Post-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Als allererste Aktion innerhalb der BSW-Task wird <code>EcuM_StartupTwo()</code> synchron aufgerufen.\n</li><li><code>EcuM</code> führt die <code>StartPostOS Sequence</code> aus (Initialisierung der verbleibenden BSW-Stacks, SchM, Start der BSW-Scheduler-Loops).\n</li><li>Nach Rückkehr von <code>EcuM_StartupTwo()</code> setzt die Task ihre reguläre Ausführung fort (z. B. Übergang in zyklische Ausführung oder Beenden via <code>TerminateTask()</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag &amp; Kontrollflussverlust:</strong> <code>StartOS()</code> kehrt gemäß OSEK/AUTOSAR OS-Spezifikation <strong>nie</strong> zum Aufrufer zurück. <code>EcuM_Init()</code> wird somit niemals regulär beendet.\n</li><li><strong>Integrationspflicht (Autostart-Task):</strong> Der System-Integrator muss zwingend eine OS-Task konfigurieren (<code>AUTOSTART = TRUE</code> im OIL/ARXML), deren <strong>allererste Anweisung</strong> der Aufruf von <code>EcuM_StartupTwo()</code> ist. Jede Verzögerung oder vorherige Task-Aktivität verletzt den Startup-Vertrag.\n</li><li><strong>Kontextbedingungen:</strong>\n<ul class=\"fig-list\"><li>In <code>StartPreOS Sequence</code> (<code>EcuM_Init</code>): Kein Tasking, keine OS-Ressourcen/Events, Interrupts typischerweise global gesperrt (<code>SuspendAllInterrupts</code> oder HW-Level). Nur zustandslose Basistreiber zulässig.\n</li><li>In <code>StartPostOS Sequence</code> (<code>EcuM_StartupTwo</code>): Voller Task-Kontext verfügbar; Inter-Modul-Kommunikation und OS-Dienste (Events, SchM) sind betriebsbereit.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Fehler in der <code>StartPreOS Sequence</code> vor Initialisierung von Dem/Det führen in hardwarenahe Trap-/Reset-Handler oder Endlosschleifen (<code>EcuM_ErrorHook</code>). Erst in <code>EcuM_StartupTwo()</code> steht die vollständige Diagnose- und Fehlerberichterstattung zur Verfügung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6bd2bffa89205b3f", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm mit Interaktionsreferenzen (<code>ref</code>-Frames / Interaction Use).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Spezifikation des ECU State Managers (<code>AUTOSAR_SWS_ECUStateManager</code>).\n</li><li><strong>Funktionaler Zweck:</strong> Darstellung der Phasenübergänge und des Kontrollflusses während der Initialisierungssequenz (<strong>STARTUP Phase</strong>) des Steuergeräts vom Hardware-Reset über den C-Laufzeitaufbau (Pre-OS) bis zur Übergabe an das Betriebssystem (OS) und die anschließende Wiederaufnahme durch den EcuM (Post-OS).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>Reset</code>: Externer Hardware-Reset-Auslöser (Power-On-Reset, Watchdog, Software-Reset).\n</li><li><code>Boot Menu</code>: Bootloader- / Hardware-Startup-Code bzw. Reset-Handler-Einsprungpunkt.\n</li><li><code>C Init Code</code>: Hardwarenaher C-Laufzeit-Startup (Zeroing <code>.bss</code>, Initialisieren von <code>.data</code>, Stack-Pointer-Konfiguration).\n</li><li><code>«module» Os</code>: AUTOSAR Operating System (Klasse: Systemdienst / Basissoftware-Modul).\n</li><li><code>BSW Task (OS task or cyclic call)</code>: Spezifische OS-Task (Autostart-Task) zur Ausführung zyklischer oder sequentieller Basissoftware-Abläufe.\n</li><li><code>«module» EcuM</code>: ECU State Manager (Klasse: Systemdienst-Modul zur zentralen Verwaltung der ECU-Zustände).\n</li></ul>\n</li><li><strong>Interaktionsreferenzen (<code>ref</code>):</strong>\n<ul class=\"fig-list\"><li><code>StartPreOS Sequence</code>: Kapselt EcuM-Initialisierungsschritte vor Start des Kernels (u. a. <code>EcuM_InitDriverInitBlock(0)</code>, Det-, Dem- und Basistreiberinitialisierung).\n</li><li><code>StartPostOS Sequence</code>: Kapselt Initialisierungsschritte nach OS-Start (u. a. Scheduler-Start via SchM, <code>BswM_Init</code>, Treiberinitialisierung Block 2/3).\n</li></ul>\n</li><li><strong>Schnittstellen / Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>Reset Vector()</code>: Hardwarespezifischer Eintrittsvektor.\n</li><li><code>Jump()</code>: Direkter Verzweigungsbefehl in die C-Laufzeit-Initialisierung.\n</li><li><code>Set up stack()</code>: Interner Aufruf zur Konfiguration der CPU-Register und Stack-Pointer.\n</li><li><code>EcuM_Init()</code>: Synchrone Einstiegs-API des EcuM vor OS-Start.\n</li><li><code>StartOS()</code>: Kernelschnittstelle zum Hochfahren des OS (übernimmt die Ausführungskontrolle).\n</li><li><code>StartupHook()</code>: Konfigurierbarer OS-Callback für anwendungsspezifischen Pre-Task-Code.\n</li><li><code>ActivateTask()</code>: OS-Systemdienst zur Aktivierung der initialen BSW-Task (bzw. impliziter Task-Start via OS-Autostart).\n</li><li><code>EcuM_StartupTwo()</code>: Synchrone EcuM-API zur Fortsetzung der Startup-Sequenz im Task-Kontext.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>Reset</code> springt den <code>Reset Vector()</code> der Bootloader-/Boot-Menu-Logik an.\n</li><li><strong>Low-Level Startup:</strong> <code>Boot Menu</code> verzweigt via <code>Jump()</code> in den <code>C Init Code</code>.\n</li><li><strong>C-Laufzeit:</strong> <code>C Init Code</code> führt <code>Set up stack()</code> aus und initialisiert Speichersektionen.\n</li><li><strong>Pre-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Synchroner Aufruf von <code>EcuM_Init()</code>.\n</li><li>Ausführung der <code>StartPreOS Sequence</code>: Minimale Hardwaretreiber-Initialisierung (u. a. MCU, Base Clocks, Pre-OS I/O) und Konfiguration der Basistreiber.\n</li></ul>\n</li><li><strong>Kontrollabgabe an das OS:</strong>\n<ul class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>StartOS()</code> auf; der Kontrollfluss verlässt die <code>EcuM_Init()</code>-Sequenz dauerhaft (kein direkter Return von <code>StartOS</code>).\n</li></ul>\n</li><li><strong>OS-Initialisierung:</strong>\n<ul class=\"fig-list\"><li>Der OS-Kernel übernimmt die CPU-Kontrolle und ruft optional den synchronen <code>StartupHook()</code> auf.\n</li><li>Das OS aktiviert die BSW-Starttask (explizit via <code>ActivateTask()</code> oder konfiguriert als <code>AUTOSTART = TRUE</code>).\n</li></ul>\n</li><li><strong>Post-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Als allererste Aktion innerhalb der BSW-Task wird <code>EcuM_StartupTwo()</code> synchron aufgerufen.\n</li><li><code>EcuM</code> führt die <code>StartPostOS Sequence</code> aus (Initialisierung der verbleibenden BSW-Stacks, SchM, Start der BSW-Scheduler-Loops).\n</li><li>Nach Rückkehr von <code>EcuM_StartupTwo()</code> setzt die Task ihre reguläre Ausführung fort (z. B. Übergang in zyklische Ausführung oder Beenden via <code>TerminateTask()</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag &amp; Kontrollflussverlust:</strong> <code>StartOS()</code> kehrt gemäß OSEK/AUTOSAR OS-Spezifikation <strong>nie</strong> zum Aufrufer zurück. <code>EcuM_Init()</code> wird somit niemals regulär beendet.\n</li><li><strong>Integrationspflicht (Autostart-Task):</strong> Der System-Integrator muss zwingend eine OS-Task konfigurieren (<code>AUTOSTART = TRUE</code> im OIL/ARXML), deren <strong>allererste Anweisung</strong> der Aufruf von <code>EcuM_StartupTwo()</code> ist. Jede Verzögerung oder vorherige Task-Aktivität verletzt den Startup-Vertrag.\n</li><li><strong>Kontextbedingungen:</strong>\n<ul class=\"fig-list\"><li>In <code>StartPreOS Sequence</code> (<code>EcuM_Init</code>): Kein Tasking, keine OS-Ressourcen/Events, Interrupts typischerweise global gesperrt (<code>SuspendAllInterrupts</code> oder HW-Level). Nur zustandslose Basistreiber zulässig.\n</li><li>In <code>StartPostOS Sequence</code> (<code>EcuM_StartupTwo</code>): Voller Task-Kontext verfügbar; Inter-Modul-Kommunikation und OS-Dienste (Events, SchM) sind betriebsbereit.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Fehler in der <code>StartPreOS Sequence</code> vor Initialisierung von Dem/Det führen in hardwarenahe Trap-/Reset-Handler oder Endlosschleifen (<code>EcuM_ErrorHook</code>). Erst in <code>EcuM_StartupTwo()</code> steht die vollständige Diagnose- und Fehlerberichterstattung zur Verfügung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-06a45c5b3a193129", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm mit Interaktionsreferenzen (<code>ref</code>-Frames / Interaction Use).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Spezifikation des ECU State Managers (<code>AUTOSAR_SWS_ECUStateManager</code>).\n</li><li><strong>Funktionaler Zweck:</strong> Darstellung der Phasenübergänge und des Kontrollflusses während der Initialisierungssequenz (<strong>STARTUP Phase</strong>) des Steuergeräts vom Hardware-Reset über den C-Laufzeitaufbau (Pre-OS) bis zur Übergabe an das Betriebssystem (OS) und die anschließende Wiederaufnahme durch den EcuM (Post-OS).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>Reset</code>: Externer Hardware-Reset-Auslöser (Power-On-Reset, Watchdog, Software-Reset).\n</li><li><code>Boot Menu</code>: Bootloader- / Hardware-Startup-Code bzw. Reset-Handler-Einsprungpunkt.\n</li><li><code>C Init Code</code>: Hardwarenaher C-Laufzeit-Startup (Zeroing <code>.bss</code>, Initialisieren von <code>.data</code>, Stack-Pointer-Konfiguration).\n</li><li><code>«module» Os</code>: AUTOSAR Operating System (Klasse: Systemdienst / Basissoftware-Modul).\n</li><li><code>BSW Task (OS task or cyclic call)</code>: Spezifische OS-Task (Autostart-Task) zur Ausführung zyklischer oder sequentieller Basissoftware-Abläufe.\n</li><li><code>«module» EcuM</code>: ECU State Manager (Klasse: Systemdienst-Modul zur zentralen Verwaltung der ECU-Zustände).\n</li></ul>\n</li><li><strong>Interaktionsreferenzen (<code>ref</code>):</strong>\n<ul class=\"fig-list\"><li><code>StartPreOS Sequence</code>: Kapselt EcuM-Initialisierungsschritte vor Start des Kernels (u. a. <code>EcuM_InitDriverInitBlock(0)</code>, Det-, Dem- und Basistreiberinitialisierung).\n</li><li><code>StartPostOS Sequence</code>: Kapselt Initialisierungsschritte nach OS-Start (u. a. Scheduler-Start via SchM, <code>BswM_Init</code>, Treiberinitialisierung Block 2/3).\n</li></ul>\n</li><li><strong>Schnittstellen / Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>Reset Vector()</code>: Hardwarespezifischer Eintrittsvektor.\n</li><li><code>Jump()</code>: Direkter Verzweigungsbefehl in die C-Laufzeit-Initialisierung.\n</li><li><code>Set up stack()</code>: Interner Aufruf zur Konfiguration der CPU-Register und Stack-Pointer.\n</li><li><code>EcuM_Init()</code>: Synchrone Einstiegs-API des EcuM vor OS-Start.\n</li><li><code>StartOS()</code>: Kernelschnittstelle zum Hochfahren des OS (übernimmt die Ausführungskontrolle).\n</li><li><code>StartupHook()</code>: Konfigurierbarer OS-Callback für anwendungsspezifischen Pre-Task-Code.\n</li><li><code>ActivateTask()</code>: OS-Systemdienst zur Aktivierung der initialen BSW-Task (bzw. impliziter Task-Start via OS-Autostart).\n</li><li><code>EcuM_StartupTwo()</code>: Synchrone EcuM-API zur Fortsetzung der Startup-Sequenz im Task-Kontext.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>Reset</code> springt den <code>Reset Vector()</code> der Bootloader-/Boot-Menu-Logik an.\n</li><li><strong>Low-Level Startup:</strong> <code>Boot Menu</code> verzweigt via <code>Jump()</code> in den <code>C Init Code</code>.\n</li><li><strong>C-Laufzeit:</strong> <code>C Init Code</code> führt <code>Set up stack()</code> aus und initialisiert Speichersektionen.\n</li><li><strong>Pre-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Synchroner Aufruf von <code>EcuM_Init()</code>.\n</li><li>Ausführung der <code>StartPreOS Sequence</code>: Minimale Hardwaretreiber-Initialisierung (u. a. MCU, Base Clocks, Pre-OS I/O) und Konfiguration der Basistreiber.\n</li></ul>\n</li><li><strong>Kontrollabgabe an das OS:</strong>\n<ul class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>StartOS()</code> auf; der Kontrollfluss verlässt die <code>EcuM_Init()</code>-Sequenz dauerhaft (kein direkter Return von <code>StartOS</code>).\n</li></ul>\n</li><li><strong>OS-Initialisierung:</strong>\n<ul class=\"fig-list\"><li>Der OS-Kernel übernimmt die CPU-Kontrolle und ruft optional den synchronen <code>StartupHook()</code> auf.\n</li><li>Das OS aktiviert die BSW-Starttask (explizit via <code>ActivateTask()</code> oder konfiguriert als <code>AUTOSTART = TRUE</code>).\n</li></ul>\n</li><li><strong>Post-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Als allererste Aktion innerhalb der BSW-Task wird <code>EcuM_StartupTwo()</code> synchron aufgerufen.\n</li><li><code>EcuM</code> führt die <code>StartPostOS Sequence</code> aus (Initialisierung der verbleibenden BSW-Stacks, SchM, Start der BSW-Scheduler-Loops).\n</li><li>Nach Rückkehr von <code>EcuM_StartupTwo()</code> setzt die Task ihre reguläre Ausführung fort (z. B. Übergang in zyklische Ausführung oder Beenden via <code>TerminateTask()</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag &amp; Kontrollflussverlust:</strong> <code>StartOS()</code> kehrt gemäß OSEK/AUTOSAR OS-Spezifikation <strong>nie</strong> zum Aufrufer zurück. <code>EcuM_Init()</code> wird somit niemals regulär beendet.\n</li><li><strong>Integrationspflicht (Autostart-Task):</strong> Der System-Integrator muss zwingend eine OS-Task konfigurieren (<code>AUTOSTART = TRUE</code> im OIL/ARXML), deren <strong>allererste Anweisung</strong> der Aufruf von <code>EcuM_StartupTwo()</code> ist. Jede Verzögerung oder vorherige Task-Aktivität verletzt den Startup-Vertrag.\n</li><li><strong>Kontextbedingungen:</strong>\n<ul class=\"fig-list\"><li>In <code>StartPreOS Sequence</code> (<code>EcuM_Init</code>): Kein Tasking, keine OS-Ressourcen/Events, Interrupts typischerweise global gesperrt (<code>SuspendAllInterrupts</code> oder HW-Level). Nur zustandslose Basistreiber zulässig.\n</li><li>In <code>StartPostOS Sequence</code> (<code>EcuM_StartupTwo</code>): Voller Task-Kontext verfügbar; Inter-Modul-Kommunikation und OS-Dienste (Events, SchM) sind betriebsbereit.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Fehler in der <code>StartPreOS Sequence</code> vor Initialisierung von Dem/Det führen in hardwarenahe Trap-/Reset-Handler oder Endlosschleifen (<code>EcuM_ErrorHook</code>). Erst in <code>EcuM_StartupTwo()</code> steht die vollständige Diagnose- und Fehlerberichterstattung zur Verfügung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-dc7f162513b3bace", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm mit Interaktionsreferenzen (<code>ref</code>-Frames / Interaction Use).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Spezifikation des ECU State Managers (<code>AUTOSAR_SWS_ECUStateManager</code>).\n</li><li><strong>Funktionaler Zweck:</strong> Darstellung der Phasenübergänge und des Kontrollflusses während der Initialisierungssequenz (<strong>STARTUP Phase</strong>) des Steuergeräts vom Hardware-Reset über den C-Laufzeitaufbau (Pre-OS) bis zur Übergabe an das Betriebssystem (OS) und die anschließende Wiederaufnahme durch den EcuM (Post-OS).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>Reset</code>: Externer Hardware-Reset-Auslöser (Power-On-Reset, Watchdog, Software-Reset).\n</li><li><code>Boot Menu</code>: Bootloader- / Hardware-Startup-Code bzw. Reset-Handler-Einsprungpunkt.\n</li><li><code>C Init Code</code>: Hardwarenaher C-Laufzeit-Startup (Zeroing <code>.bss</code>, Initialisieren von <code>.data</code>, Stack-Pointer-Konfiguration).\n</li><li><code>«module» Os</code>: AUTOSAR Operating System (Klasse: Systemdienst / Basissoftware-Modul).\n</li><li><code>BSW Task (OS task or cyclic call)</code>: Spezifische OS-Task (Autostart-Task) zur Ausführung zyklischer oder sequentieller Basissoftware-Abläufe.\n</li><li><code>«module» EcuM</code>: ECU State Manager (Klasse: Systemdienst-Modul zur zentralen Verwaltung der ECU-Zustände).\n</li></ul>\n</li><li><strong>Interaktionsreferenzen (<code>ref</code>):</strong>\n<ul class=\"fig-list\"><li><code>StartPreOS Sequence</code>: Kapselt EcuM-Initialisierungsschritte vor Start des Kernels (u. a. <code>EcuM_InitDriverInitBlock(0)</code>, Det-, Dem- und Basistreiberinitialisierung).\n</li><li><code>StartPostOS Sequence</code>: Kapselt Initialisierungsschritte nach OS-Start (u. a. Scheduler-Start via SchM, <code>BswM_Init</code>, Treiberinitialisierung Block 2/3).\n</li></ul>\n</li><li><strong>Schnittstellen / Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>Reset Vector()</code>: Hardwarespezifischer Eintrittsvektor.\n</li><li><code>Jump()</code>: Direkter Verzweigungsbefehl in die C-Laufzeit-Initialisierung.\n</li><li><code>Set up stack()</code>: Interner Aufruf zur Konfiguration der CPU-Register und Stack-Pointer.\n</li><li><code>EcuM_Init()</code>: Synchrone Einstiegs-API des EcuM vor OS-Start.\n</li><li><code>StartOS()</code>: Kernelschnittstelle zum Hochfahren des OS (übernimmt die Ausführungskontrolle).\n</li><li><code>StartupHook()</code>: Konfigurierbarer OS-Callback für anwendungsspezifischen Pre-Task-Code.\n</li><li><code>ActivateTask()</code>: OS-Systemdienst zur Aktivierung der initialen BSW-Task (bzw. impliziter Task-Start via OS-Autostart).\n</li><li><code>EcuM_StartupTwo()</code>: Synchrone EcuM-API zur Fortsetzung der Startup-Sequenz im Task-Kontext.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>Reset</code> springt den <code>Reset Vector()</code> der Bootloader-/Boot-Menu-Logik an.\n</li><li><strong>Low-Level Startup:</strong> <code>Boot Menu</code> verzweigt via <code>Jump()</code> in den <code>C Init Code</code>.\n</li><li><strong>C-Laufzeit:</strong> <code>C Init Code</code> führt <code>Set up stack()</code> aus und initialisiert Speichersektionen.\n</li><li><strong>Pre-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Synchroner Aufruf von <code>EcuM_Init()</code>.\n</li><li>Ausführung der <code>StartPreOS Sequence</code>: Minimale Hardwaretreiber-Initialisierung (u. a. MCU, Base Clocks, Pre-OS I/O) und Konfiguration der Basistreiber.\n</li></ul>\n</li><li><strong>Kontrollabgabe an das OS:</strong>\n<ul class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>StartOS()</code> auf; der Kontrollfluss verlässt die <code>EcuM_Init()</code>-Sequenz dauerhaft (kein direkter Return von <code>StartOS</code>).\n</li></ul>\n</li><li><strong>OS-Initialisierung:</strong>\n<ul class=\"fig-list\"><li>Der OS-Kernel übernimmt die CPU-Kontrolle und ruft optional den synchronen <code>StartupHook()</code> auf.\n</li><li>Das OS aktiviert die BSW-Starttask (explizit via <code>ActivateTask()</code> oder konfiguriert als <code>AUTOSTART = TRUE</code>).\n</li></ul>\n</li><li><strong>Post-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Als allererste Aktion innerhalb der BSW-Task wird <code>EcuM_StartupTwo()</code> synchron aufgerufen.\n</li><li><code>EcuM</code> führt die <code>StartPostOS Sequence</code> aus (Initialisierung der verbleibenden BSW-Stacks, SchM, Start der BSW-Scheduler-Loops).\n</li><li>Nach Rückkehr von <code>EcuM_StartupTwo()</code> setzt die Task ihre reguläre Ausführung fort (z. B. Übergang in zyklische Ausführung oder Beenden via <code>TerminateTask()</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag &amp; Kontrollflussverlust:</strong> <code>StartOS()</code> kehrt gemäß OSEK/AUTOSAR OS-Spezifikation <strong>nie</strong> zum Aufrufer zurück. <code>EcuM_Init()</code> wird somit niemals regulär beendet.\n</li><li><strong>Integrationspflicht (Autostart-Task):</strong> Der System-Integrator muss zwingend eine OS-Task konfigurieren (<code>AUTOSTART = TRUE</code> im OIL/ARXML), deren <strong>allererste Anweisung</strong> der Aufruf von <code>EcuM_StartupTwo()</code> ist. Jede Verzögerung oder vorherige Task-Aktivität verletzt den Startup-Vertrag.\n</li><li><strong>Kontextbedingungen:</strong>\n<ul class=\"fig-list\"><li>In <code>StartPreOS Sequence</code> (<code>EcuM_Init</code>): Kein Tasking, keine OS-Ressourcen/Events, Interrupts typischerweise global gesperrt (<code>SuspendAllInterrupts</code> oder HW-Level). Nur zustandslose Basistreiber zulässig.\n</li><li>In <code>StartPostOS Sequence</code> (<code>EcuM_StartupTwo</code>): Voller Task-Kontext verfügbar; Inter-Modul-Kommunikation und OS-Dienste (Events, SchM) sind betriebsbereit.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Fehler in der <code>StartPreOS Sequence</code> vor Initialisierung von Dem/Det führen in hardwarenahe Trap-/Reset-Handler oder Endlosschleifen (<code>EcuM_ErrorHook</code>). Erst in <code>EcuM_StartupTwo()</code> steht die vollständige Diagnose- und Fehlerberichterstattung zur Verfügung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2f9ffe8f3a1f8fd3", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm mit Interaktionsreferenzen (<code>ref</code>-Frames / Interaction Use).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Spezifikation des ECU State Managers (<code>AUTOSAR_SWS_ECUStateManager</code>).\n</li><li><strong>Funktionaler Zweck:</strong> Darstellung der Phasenübergänge und des Kontrollflusses während der Initialisierungssequenz (<strong>STARTUP Phase</strong>) des Steuergeräts vom Hardware-Reset über den C-Laufzeitaufbau (Pre-OS) bis zur Übergabe an das Betriebssystem (OS) und die anschließende Wiederaufnahme durch den EcuM (Post-OS).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>Reset</code>: Externer Hardware-Reset-Auslöser (Power-On-Reset, Watchdog, Software-Reset).\n</li><li><code>Boot Menu</code>: Bootloader- / Hardware-Startup-Code bzw. Reset-Handler-Einsprungpunkt.\n</li><li><code>C Init Code</code>: Hardwarenaher C-Laufzeit-Startup (Zeroing <code>.bss</code>, Initialisieren von <code>.data</code>, Stack-Pointer-Konfiguration).\n</li><li><code>«module» Os</code>: AUTOSAR Operating System (Klasse: Systemdienst / Basissoftware-Modul).\n</li><li><code>BSW Task (OS task or cyclic call)</code>: Spezifische OS-Task (Autostart-Task) zur Ausführung zyklischer oder sequentieller Basissoftware-Abläufe.\n</li><li><code>«module» EcuM</code>: ECU State Manager (Klasse: Systemdienst-Modul zur zentralen Verwaltung der ECU-Zustände).\n</li></ul>\n</li><li><strong>Interaktionsreferenzen (<code>ref</code>):</strong>\n<ul class=\"fig-list\"><li><code>StartPreOS Sequence</code>: Kapselt EcuM-Initialisierungsschritte vor Start des Kernels (u. a. <code>EcuM_InitDriverInitBlock(0)</code>, Det-, Dem- und Basistreiberinitialisierung).\n</li><li><code>StartPostOS Sequence</code>: Kapselt Initialisierungsschritte nach OS-Start (u. a. Scheduler-Start via SchM, <code>BswM_Init</code>, Treiberinitialisierung Block 2/3).\n</li></ul>\n</li><li><strong>Schnittstellen / Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>Reset Vector()</code>: Hardwarespezifischer Eintrittsvektor.\n</li><li><code>Jump()</code>: Direkter Verzweigungsbefehl in die C-Laufzeit-Initialisierung.\n</li><li><code>Set up stack()</code>: Interner Aufruf zur Konfiguration der CPU-Register und Stack-Pointer.\n</li><li><code>EcuM_Init()</code>: Synchrone Einstiegs-API des EcuM vor OS-Start.\n</li><li><code>StartOS()</code>: Kernelschnittstelle zum Hochfahren des OS (übernimmt die Ausführungskontrolle).\n</li><li><code>StartupHook()</code>: Konfigurierbarer OS-Callback für anwendungsspezifischen Pre-Task-Code.\n</li><li><code>ActivateTask()</code>: OS-Systemdienst zur Aktivierung der initialen BSW-Task (bzw. impliziter Task-Start via OS-Autostart).\n</li><li><code>EcuM_StartupTwo()</code>: Synchrone EcuM-API zur Fortsetzung der Startup-Sequenz im Task-Kontext.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>Reset</code> springt den <code>Reset Vector()</code> der Bootloader-/Boot-Menu-Logik an.\n</li><li><strong>Low-Level Startup:</strong> <code>Boot Menu</code> verzweigt via <code>Jump()</code> in den <code>C Init Code</code>.\n</li><li><strong>C-Laufzeit:</strong> <code>C Init Code</code> führt <code>Set up stack()</code> aus und initialisiert Speichersektionen.\n</li><li><strong>Pre-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Synchroner Aufruf von <code>EcuM_Init()</code>.\n</li><li>Ausführung der <code>StartPreOS Sequence</code>: Minimale Hardwaretreiber-Initialisierung (u. a. MCU, Base Clocks, Pre-OS I/O) und Konfiguration der Basistreiber.\n</li></ul>\n</li><li><strong>Kontrollabgabe an das OS:</strong>\n<ul class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>StartOS()</code> auf; der Kontrollfluss verlässt die <code>EcuM_Init()</code>-Sequenz dauerhaft (kein direkter Return von <code>StartOS</code>).\n</li></ul>\n</li><li><strong>OS-Initialisierung:</strong>\n<ul class=\"fig-list\"><li>Der OS-Kernel übernimmt die CPU-Kontrolle und ruft optional den synchronen <code>StartupHook()</code> auf.\n</li><li>Das OS aktiviert die BSW-Starttask (explizit via <code>ActivateTask()</code> oder konfiguriert als <code>AUTOSTART = TRUE</code>).\n</li></ul>\n</li><li><strong>Post-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Als allererste Aktion innerhalb der BSW-Task wird <code>EcuM_StartupTwo()</code> synchron aufgerufen.\n</li><li><code>EcuM</code> führt die <code>StartPostOS Sequence</code> aus (Initialisierung der verbleibenden BSW-Stacks, SchM, Start der BSW-Scheduler-Loops).\n</li><li>Nach Rückkehr von <code>EcuM_StartupTwo()</code> setzt die Task ihre reguläre Ausführung fort (z. B. Übergang in zyklische Ausführung oder Beenden via <code>TerminateTask()</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag &amp; Kontrollflussverlust:</strong> <code>StartOS()</code> kehrt gemäß OSEK/AUTOSAR OS-Spezifikation <strong>nie</strong> zum Aufrufer zurück. <code>EcuM_Init()</code> wird somit niemals regulär beendet.\n</li><li><strong>Integrationspflicht (Autostart-Task):</strong> Der System-Integrator muss zwingend eine OS-Task konfigurieren (<code>AUTOSTART = TRUE</code> im OIL/ARXML), deren <strong>allererste Anweisung</strong> der Aufruf von <code>EcuM_StartupTwo()</code> ist. Jede Verzögerung oder vorherige Task-Aktivität verletzt den Startup-Vertrag.\n</li><li><strong>Kontextbedingungen:</strong>\n<ul class=\"fig-list\"><li>In <code>StartPreOS Sequence</code> (<code>EcuM_Init</code>): Kein Tasking, keine OS-Ressourcen/Events, Interrupts typischerweise global gesperrt (<code>SuspendAllInterrupts</code> oder HW-Level). Nur zustandslose Basistreiber zulässig.\n</li><li>In <code>StartPostOS Sequence</code> (<code>EcuM_StartupTwo</code>): Voller Task-Kontext verfügbar; Inter-Modul-Kommunikation und OS-Dienste (Events, SchM) sind betriebsbereit.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Fehler in der <code>StartPreOS Sequence</code> vor Initialisierung von Dem/Det führen in hardwarenahe Trap-/Reset-Handler oder Endlosschleifen (<code>EcuM_ErrorHook</code>). Erst in <code>EcuM_StartupTwo()</code> steht die vollständige Diagnose- und Fehlerberichterstattung zur Verfügung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-39c498f5b0523af5", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm mit Interaktionsreferenzen (<code>ref</code>-Frames / Interaction Use).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Spezifikation des ECU State Managers (<code>AUTOSAR_SWS_ECUStateManager</code>).\n</li><li><strong>Funktionaler Zweck:</strong> Darstellung der Phasenübergänge und des Kontrollflusses während der Initialisierungssequenz (<strong>STARTUP Phase</strong>) des Steuergeräts vom Hardware-Reset über den C-Laufzeitaufbau (Pre-OS) bis zur Übergabe an das Betriebssystem (OS) und die anschließende Wiederaufnahme durch den EcuM (Post-OS).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>Reset</code>: Externer Hardware-Reset-Auslöser (Power-On-Reset, Watchdog, Software-Reset).\n</li><li><code>Boot Menu</code>: Bootloader- / Hardware-Startup-Code bzw. Reset-Handler-Einsprungpunkt.\n</li><li><code>C Init Code</code>: Hardwarenaher C-Laufzeit-Startup (Zeroing <code>.bss</code>, Initialisieren von <code>.data</code>, Stack-Pointer-Konfiguration).\n</li><li><code>«module» Os</code>: AUTOSAR Operating System (Klasse: Systemdienst / Basissoftware-Modul).\n</li><li><code>BSW Task (OS task or cyclic call)</code>: Spezifische OS-Task (Autostart-Task) zur Ausführung zyklischer oder sequentieller Basissoftware-Abläufe.\n</li><li><code>«module» EcuM</code>: ECU State Manager (Klasse: Systemdienst-Modul zur zentralen Verwaltung der ECU-Zustände).\n</li></ul>\n</li><li><strong>Interaktionsreferenzen (<code>ref</code>):</strong>\n<ul class=\"fig-list\"><li><code>StartPreOS Sequence</code>: Kapselt EcuM-Initialisierungsschritte vor Start des Kernels (u. a. <code>EcuM_InitDriverInitBlock(0)</code>, Det-, Dem- und Basistreiberinitialisierung).\n</li><li><code>StartPostOS Sequence</code>: Kapselt Initialisierungsschritte nach OS-Start (u. a. Scheduler-Start via SchM, <code>BswM_Init</code>, Treiberinitialisierung Block 2/3).\n</li></ul>\n</li><li><strong>Schnittstellen / Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>Reset Vector()</code>: Hardwarespezifischer Eintrittsvektor.\n</li><li><code>Jump()</code>: Direkter Verzweigungsbefehl in die C-Laufzeit-Initialisierung.\n</li><li><code>Set up stack()</code>: Interner Aufruf zur Konfiguration der CPU-Register und Stack-Pointer.\n</li><li><code>EcuM_Init()</code>: Synchrone Einstiegs-API des EcuM vor OS-Start.\n</li><li><code>StartOS()</code>: Kernelschnittstelle zum Hochfahren des OS (übernimmt die Ausführungskontrolle).\n</li><li><code>StartupHook()</code>: Konfigurierbarer OS-Callback für anwendungsspezifischen Pre-Task-Code.\n</li><li><code>ActivateTask()</code>: OS-Systemdienst zur Aktivierung der initialen BSW-Task (bzw. impliziter Task-Start via OS-Autostart).\n</li><li><code>EcuM_StartupTwo()</code>: Synchrone EcuM-API zur Fortsetzung der Startup-Sequenz im Task-Kontext.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>Reset</code> springt den <code>Reset Vector()</code> der Bootloader-/Boot-Menu-Logik an.\n</li><li><strong>Low-Level Startup:</strong> <code>Boot Menu</code> verzweigt via <code>Jump()</code> in den <code>C Init Code</code>.\n</li><li><strong>C-Laufzeit:</strong> <code>C Init Code</code> führt <code>Set up stack()</code> aus und initialisiert Speichersektionen.\n</li><li><strong>Pre-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Synchroner Aufruf von <code>EcuM_Init()</code>.\n</li><li>Ausführung der <code>StartPreOS Sequence</code>: Minimale Hardwaretreiber-Initialisierung (u. a. MCU, Base Clocks, Pre-OS I/O) und Konfiguration der Basistreiber.\n</li></ul>\n</li><li><strong>Kontrollabgabe an das OS:</strong>\n<ul class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>StartOS()</code> auf; der Kontrollfluss verlässt die <code>EcuM_Init()</code>-Sequenz dauerhaft (kein direkter Return von <code>StartOS</code>).\n</li></ul>\n</li><li><strong>OS-Initialisierung:</strong>\n<ul class=\"fig-list\"><li>Der OS-Kernel übernimmt die CPU-Kontrolle und ruft optional den synchronen <code>StartupHook()</code> auf.\n</li><li>Das OS aktiviert die BSW-Starttask (explizit via <code>ActivateTask()</code> oder konfiguriert als <code>AUTOSTART = TRUE</code>).\n</li></ul>\n</li><li><strong>Post-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Als allererste Aktion innerhalb der BSW-Task wird <code>EcuM_StartupTwo()</code> synchron aufgerufen.\n</li><li><code>EcuM</code> führt die <code>StartPostOS Sequence</code> aus (Initialisierung der verbleibenden BSW-Stacks, SchM, Start der BSW-Scheduler-Loops).\n</li><li>Nach Rückkehr von <code>EcuM_StartupTwo()</code> setzt die Task ihre reguläre Ausführung fort (z. B. Übergang in zyklische Ausführung oder Beenden via <code>TerminateTask()</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag &amp; Kontrollflussverlust:</strong> <code>StartOS()</code> kehrt gemäß OSEK/AUTOSAR OS-Spezifikation <strong>nie</strong> zum Aufrufer zurück. <code>EcuM_Init()</code> wird somit niemals regulär beendet.\n</li><li><strong>Integrationspflicht (Autostart-Task):</strong> Der System-Integrator muss zwingend eine OS-Task konfigurieren (<code>AUTOSTART = TRUE</code> im OIL/ARXML), deren <strong>allererste Anweisung</strong> der Aufruf von <code>EcuM_StartupTwo()</code> ist. Jede Verzögerung oder vorherige Task-Aktivität verletzt den Startup-Vertrag.\n</li><li><strong>Kontextbedingungen:</strong>\n<ul class=\"fig-list\"><li>In <code>StartPreOS Sequence</code> (<code>EcuM_Init</code>): Kein Tasking, keine OS-Ressourcen/Events, Interrupts typischerweise global gesperrt (<code>SuspendAllInterrupts</code> oder HW-Level). Nur zustandslose Basistreiber zulässig.\n</li><li>In <code>StartPostOS Sequence</code> (<code>EcuM_StartupTwo</code>): Voller Task-Kontext verfügbar; Inter-Modul-Kommunikation und OS-Dienste (Events, SchM) sind betriebsbereit.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Fehler in der <code>StartPreOS Sequence</code> vor Initialisierung von Dem/Det führen in hardwarenahe Trap-/Reset-Handler oder Endlosschleifen (<code>EcuM_ErrorHook</code>). Erst in <code>EcuM_StartupTwo()</code> steht die vollständige Diagnose- und Fehlerberichterstattung zur Verfügung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-885e41bd9171c861", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm mit Interaktionsreferenzen (<code>ref</code>-Frames / Interaction Use).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release 4.0.3), Spezifikation des ECU State Managers (<code>AUTOSAR_SWS_ECUStateManager</code>).\n</li><li><strong>Funktionaler Zweck:</strong> Darstellung der Phasenübergänge und des Kontrollflusses während der Initialisierungssequenz (<strong>STARTUP Phase</strong>) des Steuergeräts vom Hardware-Reset über den C-Laufzeitaufbau (Pre-OS) bis zur Übergabe an das Betriebssystem (OS) und die anschließende Wiederaufnahme durch den EcuM (Post-OS).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure &amp; Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>Reset</code>: Externer Hardware-Reset-Auslöser (Power-On-Reset, Watchdog, Software-Reset).\n</li><li><code>Boot Menu</code>: Bootloader- / Hardware-Startup-Code bzw. Reset-Handler-Einsprungpunkt.\n</li><li><code>C Init Code</code>: Hardwarenaher C-Laufzeit-Startup (Zeroing <code>.bss</code>, Initialisieren von <code>.data</code>, Stack-Pointer-Konfiguration).\n</li><li><code>«module» Os</code>: AUTOSAR Operating System (Klasse: Systemdienst / Basissoftware-Modul).\n</li><li><code>BSW Task (OS task or cyclic call)</code>: Spezifische OS-Task (Autostart-Task) zur Ausführung zyklischer oder sequentieller Basissoftware-Abläufe.\n</li><li><code>«module» EcuM</code>: ECU State Manager (Klasse: Systemdienst-Modul zur zentralen Verwaltung der ECU-Zustände).\n</li></ul>\n</li><li><strong>Interaktionsreferenzen (<code>ref</code>):</strong>\n<ul class=\"fig-list\"><li><code>StartPreOS Sequence</code>: Kapselt EcuM-Initialisierungsschritte vor Start des Kernels (u. a. <code>EcuM_InitDriverInitBlock(0)</code>, Det-, Dem- und Basistreiberinitialisierung).\n</li><li><code>StartPostOS Sequence</code>: Kapselt Initialisierungsschritte nach OS-Start (u. a. Scheduler-Start via SchM, <code>BswM_Init</code>, Treiberinitialisierung Block 2/3).\n</li></ul>\n</li><li><strong>Schnittstellen / Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>Reset Vector()</code>: Hardwarespezifischer Eintrittsvektor.\n</li><li><code>Jump()</code>: Direkter Verzweigungsbefehl in die C-Laufzeit-Initialisierung.\n</li><li><code>Set up stack()</code>: Interner Aufruf zur Konfiguration der CPU-Register und Stack-Pointer.\n</li><li><code>EcuM_Init()</code>: Synchrone Einstiegs-API des EcuM vor OS-Start.\n</li><li><code>StartOS()</code>: Kernelschnittstelle zum Hochfahren des OS (übernimmt die Ausführungskontrolle).\n</li><li><code>StartupHook()</code>: Konfigurierbarer OS-Callback für anwendungsspezifischen Pre-Task-Code.\n</li><li><code>ActivateTask()</code>: OS-Systemdienst zur Aktivierung der initialen BSW-Task (bzw. impliziter Task-Start via OS-Autostart).\n</li><li><code>EcuM_StartupTwo()</code>: Synchrone EcuM-API zur Fortsetzung der Startup-Sequenz im Task-Kontext.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>Reset</code> springt den <code>Reset Vector()</code> der Bootloader-/Boot-Menu-Logik an.\n</li><li><strong>Low-Level Startup:</strong> <code>Boot Menu</code> verzweigt via <code>Jump()</code> in den <code>C Init Code</code>.\n</li><li><strong>C-Laufzeit:</strong> <code>C Init Code</code> führt <code>Set up stack()</code> aus und initialisiert Speichersektionen.\n</li><li><strong>Pre-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Synchroner Aufruf von <code>EcuM_Init()</code>.\n</li><li>Ausführung der <code>StartPreOS Sequence</code>: Minimale Hardwaretreiber-Initialisierung (u. a. MCU, Base Clocks, Pre-OS I/O) und Konfiguration der Basistreiber.\n</li></ul>\n</li><li><strong>Kontrollabgabe an das OS:</strong>\n<ul class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>StartOS()</code> auf; der Kontrollfluss verlässt die <code>EcuM_Init()</code>-Sequenz dauerhaft (kein direkter Return von <code>StartOS</code>).\n</li></ul>\n</li><li><strong>OS-Initialisierung:</strong>\n<ul class=\"fig-list\"><li>Der OS-Kernel übernimmt die CPU-Kontrolle und ruft optional den synchronen <code>StartupHook()</code> auf.\n</li><li>Das OS aktiviert die BSW-Starttask (explizit via <code>ActivateTask()</code> oder konfiguriert als <code>AUTOSTART = TRUE</code>).\n</li></ul>\n</li><li><strong>Post-OS Phase (EcuM):</strong>\n<ul class=\"fig-list\"><li>Als allererste Aktion innerhalb der BSW-Task wird <code>EcuM_StartupTwo()</code> synchron aufgerufen.\n</li><li><code>EcuM</code> führt die <code>StartPostOS Sequence</code> aus (Initialisierung der verbleibenden BSW-Stacks, SchM, Start der BSW-Scheduler-Loops).\n</li><li>Nach Rückkehr von <code>EcuM_StartupTwo()</code> setzt die Task ihre reguläre Ausführung fort (z. B. Übergang in zyklische Ausführung oder Beenden via <code>TerminateTask()</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag &amp; Kontrollflussverlust:</strong> <code>StartOS()</code> kehrt gemäß OSEK/AUTOSAR OS-Spezifikation <strong>nie</strong> zum Aufrufer zurück. <code>EcuM_Init()</code> wird somit niemals regulär beendet.\n</li><li><strong>Integrationspflicht (Autostart-Task):</strong> Der System-Integrator muss zwingend eine OS-Task konfigurieren (<code>AUTOSTART = TRUE</code> im OIL/ARXML), deren <strong>allererste Anweisung</strong> der Aufruf von <code>EcuM_StartupTwo()</code> ist. Jede Verzögerung oder vorherige Task-Aktivität verletzt den Startup-Vertrag.\n</li><li><strong>Kontextbedingungen:</strong>\n<ul class=\"fig-list\"><li>In <code>StartPreOS Sequence</code> (<code>EcuM_Init</code>): Kein Tasking, keine OS-Ressourcen/Events, Interrupts typischerweise global gesperrt (<code>SuspendAllInterrupts</code> oder HW-Level). Nur zustandslose Basistreiber zulässig.\n</li><li>In <code>StartPostOS Sequence</code> (<code>EcuM_StartupTwo</code>): Voller Task-Kontext verfügbar; Inter-Modul-Kommunikation und OS-Dienste (Events, SchM) sind betriebsbereit.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Fehler in der <code>StartPreOS Sequence</code> vor Initialisierung von Dem/Det führen in hardwarenahe Trap-/Reset-Handler oder Endlosschleifen (<code>EcuM_ErrorHook</code>). Erst in <code>EcuM_StartupTwo()</code> steht die vollständige Diagnose- und Fehlerberichterstattung zur Verfügung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-64b9aa2365081762", "to": "FIG-e330869822abb792", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e330869822abb792", "to": "FIG-6bd2bffa89205b3f", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6bd2bffa89205b3f", "to": "FIG-06a45c5b3a193129", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-06a45c5b3a193129", "to": "FIG-dc7f162513b3bace", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-dc7f162513b3bace", "to": "FIG-2f9ffe8f3a1f8fd3", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Lifeline «module» Os: Das Modul-Icon in der unteren rechten Ecke des Lifeline-Kopfes wurde entfernt.\n</li></ul>"}, {"from": "FIG-2f9ffe8f3a1f8fd3", "to": "FIG-39c498f5b0523af5", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-39c498f5b0523af5", "to": "FIG-885e41bd9171c861", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Reset Vector()</strong>: Zeilenumbruch behoben, Beschriftung nun einzeilig.\n</li><li><strong>Set up stack()</strong>: Zeilenumbruch behoben, Beschriftung nun einzeilig.\n</li><li><strong>EcuM_StartupTwo()</strong>: Zeilenumbruch („wo()“) behoben, Signatur nun einzeilig dargestellt.\n</li><li><strong>StartPreOS Sequence</strong>: Interaktionsrahmen (<code>ref</code>) horizontal angepasst, wodurch die visuelle Kollision mit dem Pfeil von <code>StartOS()</code> bereinigt wurde.\n</li></ul>"}]};
